/* the agent passes a conversation to a person: why, who has it (with Reassign), when the reply is due, what they need to
   pick it up, and what the customer was told. The type and spacing are Draft review's; the two columns stack when narrow */
.dm-hox{position:relative;width:100%;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-hox-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.dm-hox-ic{width:32px;height:32px;border-radius:9px;background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.dm-hox-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-hox-ht b{font-weight:500;font-size:14px}
.dm-hox-ht span{font-size:13px}
.dm-hox-b{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--dm-s-4) var(--dm-s-6);align-items:start;padding-top:var(--dm-s-3);border-top:1px solid var(--dm-line)}
@container (max-width:600px){.dm-hox-b{grid-template-columns:minmax(0,1fr)}.dm-hox-col+.dm-hox-col{padding-top:var(--dm-s-3);border-top:1px solid var(--dm-line)}}
.dm-hox-col{display:flex;flex-direction:column;gap:var(--dm-s-2);min-width:0}
.dm-hox-lb{font-size:12px;color:var(--dm-muted)}
.dm-hox-who{display:flex;align-items:center;gap:10px;min-height:40px}
.dm-hox-av{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:50%;background:var(--dm-chip);color:var(--dm-fg2)}
.dm-hox-av .dm-av{width:28px;height:28px;font-size:11px}
.dm-hox-wt{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-hox-wt b{font-weight:500;font-size:13.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-hox-wd{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-hox-wd .dm-dot{color:var(--dm-faint)}
.dm-hox-wd.dm-ok .dm-dot{color:var(--dm-ok)}
.dm-hox-wd.dm-warn,.dm-hox-wd.dm-warn .dm-dot{color:var(--dm-warn)}
/* Reassign: a small dropdown, like the one for how long in Permission gate */
.dm-hox-rb{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 var(--dm-s-2) 0 10px;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);flex:none;transition:background .16s,color .16s}
.dm-hox-rb[aria-expanded="true"]{background:var(--dm-chip);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.dm-hox-rb:hover{background:var(--dm-chip);color:var(--dm-fg)}}
