.dm-hox-pop .dm-mi>span:not(.dm-ck):not(.dm-av){flex:1;min-width:0}
/* when the reply is due: the line counts down and the bar empties, amber in the last five minutes */
.dm-hox-sla{display:flex;flex-direction:column;gap:var(--dm-s-2);padding-top:var(--dm-s-2)}
.dm-hox-sl{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px}
.dm-hox-sl>svg{color:var(--dm-fg2);flex:none}
.dm-hox-sl .dm-muted{margin-left:auto;font-size:12px;white-space:nowrap}
.dm-hox-due{min-width:0}
.dm-hox-bar{height:4px;border-radius:2px;background:var(--dm-chip);overflow:hidden}
.dm-hox-bar i{display:block;height:100%;width:100%;border-radius:inherit;background:var(--dm-fg2);transition:width 1s linear,background .3s}
.dm-hox-sla.dm-warn .dm-hox-sl>svg,.dm-hox-sla.dm-warn .dm-hox-due{color:var(--dm-warn)}
.dm-hox-sla.dm-warn .dm-hox-bar i{background:var(--dm-warn)}
.dm-hox-sla.dm-bad .dm-hox-sl>svg,.dm-hox-sla.dm-bad .dm-hox-due{color:var(--dm-bad)}
.dm-hox-sum{margin:0;font-size:13px;line-height:1.5;color:var(--dm-fg2)}
.dm-hox-facts{display:flex;flex-direction:column;border-bottom:1px solid var(--dm-line)}
.dm-hox-f{display:flex;align-items:center;gap:10px;min-height:32px;border-top:1px solid var(--dm-line);font-size:13px}
.dm-hox-f .dm-k{width:72px;flex:none;color:var(--dm-muted)}
.dm-hox-f .dm-v{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-hox-lnk{align-self:flex-start;max-width:100%}
.dm-hox-lnk>span{overflow:hidden;text-overflow:ellipsis}
/* what the customer was told, editable in place */
.dm-hox-ms{display:flex;flex-direction:column;gap:var(--dm-s-2);margin-top:var(--dm-s-1);padding-top:var(--dm-s-3);border-top:1px solid var(--dm-line)}
.dm-hox-mh{display:flex;align-items:center;gap:var(--dm-s-2);min-height:28px}
.dm-hox-mh .dm-sp{flex:1}
.dm-hox-mb{padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-chip);font-size:13.5px;line-height:1.5;outline:0;transition:box-shadow var(--dm-t-fast),background var(--dm-t-fast)}
.dm-hox-mb[contenteditable="true"]{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-field-line)}
@supports (corner-shape:squircle){.dm-hox-mb[contenteditable="true"]{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.dm-hox-mb[contenteditable="true"]:focus{box-shadow:inset 0 0 0 1px var(--dm-field-line-strong)}
/* where it stands, in one row at the foot: neutral while it waits, amber when the person can't take it, green once they have */
.dm-hox-st{display:flex;align-items:center;gap:var(--dm-s-3);padding:10px 10px 10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-chip);font-size:13.5px;transition:background .32s}
.dm-hox-st.dm-warn{background:var(--dm-warn-bg)}
.dm-hox-st.dm-ok{background:var(--dm-ok-bg)}
.dm-hox-st .dm-g{width:18px;height:18px;display:grid;place-items:center;flex:none;color:var(--dm-fg2)}
.dm-hox-st.dm-warn .dm-g{color:var(--dm-warn)}
.dm-hox-st.dm-ok .dm-g{color:var(--dm-ok)}
.dm-hox-st .dm-g .dm-av{width:18px;height:18px;font-size:8.5px}
.dm-hox-st .dm-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-hox-st .dm-t b{font-weight:400}
/* the second line sits on the row's tint, so it is fg2 rather than muted */
.dm-hox-st .dm-t>span{font-size:13px;color:var(--dm-fg2)}
.dm-hox-st .dm-t,.dm-hox-sum,.dm-hox-mb,.dm-tmx-note>span{text-wrap:pretty}

